// A real ~9km loop around Golden Gate Park / the Panhandle, encoded as a
// Strava summary polyline would be.
function encode(points: [number, number][]): string {
  let out = "";
  let lastLat = 0;
  let lastLng = 0;
  const chunk = (value: number): string => {
    let v = value < 0 ? ~(value << 1) : value << 1;
    let s = "";
    while (v >= 0x20) {
      s += String.fromCharCode((0x20 | (v & 0x1f)) + 63);
      v >>= 5;
    }
    return s + String.fromCharCode(v + 63);
  };
  for (const [lat, lng] of points) {
    const la = Math.round(lat * 1e5);
    const ln = Math.round(lng * 1e5);
    out += chunk(la - lastLat) + chunk(ln - lastLng);
    lastLat = la;
    lastLng = ln;
  }
  return out;
}

const LOOP: [number, number][] = [];
// Out along the Panhandle, a lap of the park's east end, and back.
const path: [number, number][] = [
  [37.7727, -122.4478],
  [37.7729, -122.4530],
  [37.7731, -122.4590],
  [37.7715, -122.4640],
  [37.7695, -122.4680],
  [37.7683, -122.4720],
  [37.7690, -122.4780],
  [37.7712, -122.4830],
  [37.7735, -122.4790],
  [37.7742, -122.4720],
  [37.7738, -122.4650],
  [37.7734, -122.4580],
  [37.7730, -122.4510],
  [37.7726, -122.4470],
];
for (let i = 0; i < path.length; i++) {
  const [lat, lng] = path[i]!;
  LOOP.push([lat, lng]);
  const next = path[i + 1];
  if (next) {
    for (let t = 1; t < 6; t++) {
      LOOP.push([lat + ((next[0] - lat) * t) / 6, lng + ((next[1] - lng) * t) / 6]);
    }
  }
}

